import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

MODEL = "gpt-6.1-sol"
SEED = 20261113

DOMAINS = [
    "cooking a weeknight dinner", "baking bread", "meal prep", "grocery planning", "coffee brewing", "tea",
    "weather and clothing", "travel planning", "train and flight logistics", "hiking", "camping", "gardening",
    "houseplants", "home repair", "cleaning tips", "laundry", "home organisation", "moving house", "renting basics",
    "personal budgeting", "saving money", "basic taxes", "fitness routines", "running", "yoga and stretching",
    "sleep habits", "nutrition facts", "learning a language", "math homework", "science questions", "history trivia",
    "geography", "astronomy", "birdwatching", "pet care", "dog training", "cat care", "car maintenance",
    "cycling", "photography", "drawing and painting", "knitting", "woodworking", "board games", "card games",
    "sports rules", "music theory", "learning guitar", "books and reading", "film recommendations", "podcasts",
    "computer troubleshooting", "spreadsheet formulas", "writing an email", "time management", "unit conversions",
    "recipes for kids", "party planning", "gift ideas", "holiday planning",
]

INSTRUCTIONS = (
    "You write short spoken utterances for a research dataset about voice assistants at home. Use natural, everyday "
    "spoken English: contractions are fine, no stage directions, no emojis, no quotation marks inside the text. "
    "Never use personal names, brand names or a wake word. Return only JSON that matches the schema.")

CONV_PROMPT = (
    "Write {n} different short exchanges between a person at home and their voice assistant, one per topic, using "
    "these topics in this order: {topics}.\n"
    "For each exchange give:\n"
    "- topic: the topic (2-6 words);\n"
    "- user_request: what the person asks the assistant, one spoken sentence of 8-20 words;\n"
    "- agent_answer: the assistant's answer, 1-3 sentences, 15-45 words;\n"
    "- user_followup: a natural follow-up question to the assistant, one sentence of 6-18 words.\n"
    "Constraints: do not mention phones, calls, doors, doorbells, knocking, visitors, deliveries, family members, "
    "children, roommates or any other person in the home; do not mention the assistant pausing or waiting.")

ANGLES = ["a specific measurement or quantity", "troubleshooting something that went wrong", "comparing two options",
          "doing it within a time limit", "a common beginner mistake", "an unusual situation", "a budget constraint",
          "a step-by-step how-to for one detail", "a safety or care consideration", "planning ahead for next week",
          "a fact or definition", "adapting it for a small apartment", "doing it with limited tools",
          "a seasonal consideration"]
CONV_PROMPT_V2 = CONV_PROMPT + (
    "\nMake every request specific and different from the most common beginner questions on that topic. For each "
    "exchange, use the angle given with its topic. Topics with angles: {topic_angles}.")

POOL_PROMPTS = {
    "he_door": (
        "Write {n} different short things a person says TO THEIR VOICE ASSISTANT right after {event}, to tell the "
        "assistant they have to deal with it for a moment. Each one must clearly be addressed to the assistant, "
        "not to the visitor. Each must make sense whether or not the assistant was talking at that moment: do not "
        "ask the assistant to stop, pause, be quiet or hold that thought. 3-10 words each. Vary the wording a lot."),
    "he_phone": (
        "Write {n} different short things a person says TO THEIR VOICE ASSISTANT right after {event}, to tell the "
        "assistant they have to take it for a moment. Each one must clearly be addressed to the assistant, not to "
        "the caller. Each must make sense whether or not the assistant was talking at that moment: do not ask the "
        "assistant to stop, pause, be quiet or hold that thought. 3-10 words each. Vary the wording a lot."),
    "f3_pair": (
        "Write {n} different pairs. family_call: a family member in another room calls out to the person, 4-12 "
        "words, no names. user_reply: the person's short reply, 1-6 words, of a kind that would also be a natural "
        "thing to say to a voice assistant when nobody else had spoken (for example asking it to repeat)."),
    "b2_side": (
        "Write {n} different short things a person at home says to ANOTHER PERSON in the same room (not to a voice "
        "assistant), 4-14 words each, about everyday household matters. No names."),
    "r_line": (
        "Write {n} different short things a person says to their voice assistant when they come back after "
        "stepping away for a minute, to pick the conversation up again. 3-12 words each."),
    "phone_flip": (
        "Write {n} different very short things people say when they answer a ringing phone, 1-6 words each. "
        "Prefer ones that would also be natural to say to a voice assistant to check whether it is listening "
        "(for example a plain greeting). Include very common ones and less common ones."),
    "door_flip": (
        "Write {n} different very short things people call out towards the front door after someone knocks or "
        "rings the doorbell, 1-6 words each. Prefer ones that would also be natural to say to a voice assistant "
        "to check whether it is listening (for example a plain greeting or 'yes?'). Include very common ones and "
        "less common ones."),
}
EVENTS = {"he_door": ["someone knocks on the front door", "the doorbell rings"],
          "he_phone": ["their mobile phone starts ringing", "the landline phone rings"]}
POOL_PLAN = {"he_door": (10, 40), "he_phone": (10, 40), "f3_pair": (8, 40), "b2_side": (10, 40), "r_line": (4, 40),
             "phone_flip": (1, 40), "door_flip": (1, 40)}
N_CONV_BATCHES, CONV_BATCH = 90, 20                      # 1,800 candidates for 1,600 conversations after dedup


def schema(kind):
    if kind == "conversations":
        item = {"type": "object", "additionalProperties": False,
                "properties": {k: {"type": "string"} for k in ("topic", "user_request", "agent_answer",
                                                               "user_followup")},
                "required": ["topic", "user_request", "agent_answer", "user_followup"]}
    elif kind == "f3_pair":
        item = {"type": "object", "additionalProperties": False,
                "properties": {"family_call": {"type": "string"}, "user_reply": {"type": "string"}},
                "required": ["family_call", "user_reply"]}
    else:
        item = {"type": "string"}
    return {"type": "object", "additionalProperties": False, "properties": {"items": {"type": "array", "items": item}},
            "required": ["items"]}


def call(key, prompt, kind, raw_path):
    body = {"model": MODEL, "instructions": INSTRUCTIONS, "input": prompt,
            "text": {"format": {"type": "json_schema", "name": "batch", "schema": schema(kind), "strict": True}}}
    for attempt in range(5):
        req = urllib.request.Request("https://api.openai.com/v1/responses", data=json.dumps(body).encode("utf-8"),
                                     headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=300) as r:
                js = json.loads(r.read().decode("utf-8"))
            text = "".join(c.get("text", "") for o in js.get("output", []) if o.get("type") == "message"
                           for c in o.get("content", []))
            json.dump({"prompt": prompt, "response": js}, open(raw_path, "w", encoding="utf-8"), ensure_ascii=False)
            return json.loads(text)["items"], js.get("usage", {})
        except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError, KeyError, TimeoutError,
                OSError, http.client.HTTPException):
            if attempt == 4:
                raise
            time.sleep(10 * (attempt + 1))


def main(key_path, out_dir, what="all"):
    key = next(str(v).strip() for k, v in json.load(open(key_path, encoding="utf-8")).items()
               if k in ("OPENAI_API_KEY", "api_key") and v)
    os.makedirs(os.path.join(out_dir, "raw"), exist_ok=True)
    rng = random.Random(SEED)
    usage = {"input_tokens": 0, "output_tokens": 0}
    if what in ("all", "conversations"):
        convs = []
        for b in range(N_CONV_BATCHES):
            topics = rng.sample(DOMAINS, CONV_BATCH)
            items, u = call(key, CONV_PROMPT.format(n=CONV_BATCH, topics="; ".join(topics)), "conversations",
                            os.path.join(out_dir, "raw", f"conv_{b:03d}.json"))
            for k in usage:
                usage[k] += u.get(k, 0)
            convs += [{**it, "batch": b} for it in items]
            print(f"conversations batch {b}: {len(items)} (total {len(convs)})", flush=True)
        json.dump(convs, open(os.path.join(out_dir, "conversations_candidates.json"), "w", encoding="utf-8"),
                  indent=1, ensure_ascii=False)
    if what == "conversations_extra":                    # prompt v2: more specific requests (added 11-13)
        rng2 = random.Random(SEED + 1)
        extra = []
        for b in range(50):
            topics = rng2.sample(DOMAINS, CONV_BATCH)
            ta = "; ".join(f"{t} ({rng2.choice(ANGLES)})" for t in topics)
            items, u = call(key, CONV_PROMPT_V2.format(n=CONV_BATCH, topics="; ".join(topics), topic_angles=ta),
                            "conversations", os.path.join(out_dir, "raw", f"convx_{b:03d}.json"))
            for k in usage:
                usage[k] += u.get(k, 0)
            extra += [{**it, "batch": 1000 + b, "prompt_version": 2} for it in items]
            print(f"extra conversations batch {b}: {len(items)} (total {len(extra)})", flush=True)
        json.dump(extra, open(os.path.join(out_dir, "conversations_candidates_extra.json"), "w", encoding="utf-8"),
                  indent=1, ensure_ascii=False)
    if what in ("all", "pools"):
        pools = {}
        for kind, (n_batches, n) in POOL_PLAN.items():
            pools[kind] = []
            for b in range(n_batches):
                event = EVENTS[kind][b % 2] if kind in EVENTS else ""
                items, u = call(key, POOL_PROMPTS[kind].format(n=n, event=event),
                                "f3_pair" if kind == "f3_pair" else "lines",
                                os.path.join(out_dir, "raw", f"{kind}_{b:02d}.json"))
                for k in usage:
                    usage[k] += u.get(k, 0)
                pools[kind] += [{"text": it, "event": event} if isinstance(it, str) else {**it, "event": event}
                                for it in items]
            print(f"pool {kind}: {len(pools[kind])}", flush=True)
        json.dump(pools, open(os.path.join(out_dir, "pools_candidates.json"), "w", encoding="utf-8"), indent=1,
                  ensure_ascii=False)
    print("usage", usage, "approx cost $", round(usage["input_tokens"] * 2e-6 + usage["output_tokens"] * 10e-6, 2))


if __name__ == "__main__":
    main(*sys.argv[1:4])
